import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"53、【漸】 艮下巽上","description":"周易口訣義 - 53、【漸】 艮下巽上","frontmatter":{"title":"53、【漸】 艮下巽上","description":"周易口訣義 - 53、【漸】 艮下巽上"},"headers":[],"relativePath":"classics/koujueyi/055.md","filePath":"classics/koujueyi/055.md"}'),r={name:"classics/koujueyi/055.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_53、【漸】-艮下巽上" tabindex="-1">53、【漸】 艮下巽上 <a class="header-anchor" href="#_53、【漸】-艮下巽上" aria-label="Permalink to “53、【漸】 艮下巽上”">​</a></h1><p>彖曰：漸之進也，「女歸吉」也。進得位，往有功也；進以正，可以正邦也。其位剛得中也；止而巽，動不窮也。</p><p>象曰：山上有木，漸，君子以居賢德善俗。</p><p>初六，鴻漸於幹，小子厲，有言無咎。</p><p>象曰：小子之厲，義無咎也。</p><p>六二，鴻漸於磐，飲食衎衎，吉。</p><p>象曰：「飲食衎衎」，不素飽也。</p><p>九三，鴻漸於陸，夫徵不復，婦孕不育，兇。利禦寇。</p><p>象曰：「夫徵不復」，離群醜也；「婦孕不復」，失其道也。「利用禦寇」，順相保也。</p><p>六四，鴻漸於木，或得其桷，無咎。</p><p>象曰：「或得其桷」，順以巽也。</p><p>九五，鴻漸於陵，婦三歲不孕，終莫之勝，吉。</p><p>象曰：「終莫之勝吉」，得所願也。</p><p>上九，鴻漸於陸，其羽可用為儀，吉。</p><p>象曰：「其羽可用為儀吉」，不可亂也。</p><p>解讀</p><p>漸女歸吉利貞者，漸者徐進之名，歸嫁也。女子生有外成之義，以夫為家，故嫁為歸也。女人之嫁，備禮乃行，吉斯善矣，故曰「女歸吉」也。漸進禮，全嫁娶之正，故曰「利貞」也。象曰：「山上有木，漸」者，山上生木，漸漸進長，因山而高，非是忽然而起，故曰「漸之進」也。君子以居賢德善俗者，君子求人，須求賢德，使其居位，發施教令，善誘風俗也。侯果雲：「賢者，德成之名，德是資賢之實也。」</p><p>「初六，鴻漸於幹，小子厲，有言，無咎」者，鴻是水鳥，以況從下至高漸進之義；幹，水涯也。鴻之進至於水涯，故曰「鴻漸於幹」也。進未得位，必被凌辱，乃困於小子，危於謗言，故曰「小子厲，有言」也。雖困於小人之言，而但懷道德，安能損於君子之道？故曰「無咎」也。幹亦喻水上，非安之所，更以無應也。</p><p>「六二，鴻漸於磐，飲食衎衎，吉」者，磐者，山中磐石也。以柔處中，進而得位，猶鴻鳥棲於磐石，得可安之地，故曰「鴻漸於磐」。既得可安之地，居中有應，吉福至焉，故飲食豐飽，不素飽而已，故曰「衎衎吉」也。「衎衎」是喜樂之貌也。</p><p>「九三，鴻漸於陸，夫徵不復，婦孕不育，兇。利用禦寇」者，陸是山頂之高處也。九三處下卦之上，如山之頂，如鴻升進至於山頂，故曰「鴻漸於陸」也。三之於二，同處一體，其猶夫婦一體之義。今九三務進，不肯卻回，即是夫之徵進，不肯反家，故曰「夫徵不復」也。九三前進，與四相得，貪務邪偶，即婦亦不能守貞，非夫而孕，故不能育，故曰「婦孕不育」也。見利忘義，貪進忘舊，兇之道矣。與四相得，邪偶相與，恐人為難，以為間阻，故利用防禦寇害，順相保也。</p><p>六四，鴻漸於木，或得其桷，無咎者，桷，榱桷也。以柔得位，如鴻棲於平直之枝，堪榱桷之用，是可棲息之處，故曰「鴻漸於木，或得其桷」。與三相得，心無憂慮，雖乘剛相合，固無咎也。</p><p>九五，鴻漸於陵，婦三歲不孕，終莫之勝，吉。陸績雲：陸、陵俱是高處，然陵卑於陸也。九五進處尊位，如鴻進高以止於陵，故曰「鴻漸於陵」也。正應在二，隔於三、四，不得與應相交，是兩情勤慕，阻隔不通，故曰「三歲不孕」也。二與五各懷中正，九五是君，三四是臣，以臣欺君，勢不可勝。三歲以來，道成事濟，久塞其路，不得勝於君。五、二各得其願，故曰「終莫之勝，吉」也。</p><p>上九：鴻漸於陸，其羽可用為儀，吉者，三之於上，皆處山頂，並稱「陸」也。然上九最居卦上，是能為超勝，進處高潔，不累名位。德高之人，無物屈心，不亂其志，故其羽翼清虛，可為世之儀表，峨峨清奇，可貴可則，故曰「其羽可用為儀，吉」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
